-- 000900_wiki_entity_types_seed.down.sql
-- Reverses 000900: removes the new wiki types' parent edges, configs,
-- space_types type keys, and the entity-kind registry rows.

BEGIN;

DELETE FROM wiki_type_parents
WHERE space_type_id IN (
    '00000000-0000-0000-0000-000000000072', '00000000-0000-0000-0000-000000000073',
    '00000000-0000-0000-0000-000000000074', '00000000-0000-0000-0000-000000000075',
    '00000000-0000-0000-0000-000000000076', '00000000-0000-0000-0000-000000000077',
    '00000000-0000-0000-0000-000000000078', '00000000-0000-0000-0000-000000000079',
    '00000000-0000-0000-0000-00000000007a', '00000000-0000-0000-0000-00000000007b',
    '00000000-0000-0000-0000-00000000007c', '00000000-0000-0000-0000-00000000007d'
);

DELETE FROM wiki_type_configs
WHERE space_type_id IN (
    '00000000-0000-0000-0000-000000000072', '00000000-0000-0000-0000-000000000073',
    '00000000-0000-0000-0000-000000000074', '00000000-0000-0000-0000-000000000075',
    '00000000-0000-0000-0000-000000000076', '00000000-0000-0000-0000-000000000077',
    '00000000-0000-0000-0000-000000000078', '00000000-0000-0000-0000-000000000079',
    '00000000-0000-0000-0000-00000000007a', '00000000-0000-0000-0000-00000000007b',
    '00000000-0000-0000-0000-00000000007c', '00000000-0000-0000-0000-00000000007d'
);

DELETE FROM space_types
WHERE id IN (
    '00000000-0000-0000-0000-000000000072', '00000000-0000-0000-0000-000000000073',
    '00000000-0000-0000-0000-000000000074', '00000000-0000-0000-0000-000000000075',
    '00000000-0000-0000-0000-000000000076', '00000000-0000-0000-0000-000000000077',
    '00000000-0000-0000-0000-000000000078', '00000000-0000-0000-0000-000000000079',
    '00000000-0000-0000-0000-00000000007a', '00000000-0000-0000-0000-00000000007b',
    '00000000-0000-0000-0000-00000000007c', '00000000-0000-0000-0000-00000000007d'
);

DELETE FROM wiki_entity_kinds
WHERE entity_kind IN ('visa_route', 'organization', 'course', 'scholarship', 'embassy');

COMMIT;
